options(warn = 1)
args <- commandArgs(trailingOnly = TRUE)
mode <- if (length(args) >= 1) args[[1]] else 'run'
config_path <- if (length(args) >= 2) args[[2]] else NA_character_
if (!requireNamespace('jsonlite', quietly = TRUE)) { cat('APP_EVENT:{"type":"fatal","stage":"bootstrap","message":"Package jsonlite tidak tersedia."}\n'); quit(status=10) }
suppressPackageStartupMessages({ library(sf); library(dplyr) })
`%||%` <- function(a,b) if(is.null(a)||length(a)==0||all(is.na(a))) b else a
as_num <- function(x,d=NA_real_) { y<-suppressWarnings(as.numeric(x)); if(!length(y)||!is.finite(y[1]))d else y[1] }
emit <- function(type,...,.list=list()) { payload<-c(list(type=type,timestamp=format(Sys.time(),'%Y-%m-%dT%H:%M:%S')),list(...),.list);cat('APP_EVENT:',jsonlite::toJSON(payload,auto_unbox=TRUE,null='null',na='null'),'\n',sep='');try(flush(stdout()),silent=TRUE);flush.console() }
if(is.na(config_path)||!file.exists(config_path)){emit('fatal',stage='bootstrap',message='Config JSON tidak ditemukan.');quit(status=10)}
cfg<-jsonlite::fromJSON(config_path,simplifyVector=FALSE);inputs<-cfg$inputs%||%list();run_dir<-normalizePath(cfg$app$run_dir%||%dirname(config_path),winslash='/',mustWork=FALSE);dir.create(run_dir,recursive=TRUE,showWarnings=FALSE);shp_dir<-file.path(run_dir,'shapefile');qc_dir<-file.path(run_dir,'qc');dir.create(shp_dir,recursive=TRUE,showWarnings=FALSE);dir.create(qc_dir,recursive=TRUE,showWarnings=FALSE);log_path<-file.path(run_dir,'analysis.log');if(file.exists(log_path))file.remove(log_path);current_stage<-'bootstrap'
write_log<-function(level='INFO',message){cat(sprintf('[%s] [%s] [%s] %s\n',format(Sys.time(),'%Y-%m-%d %H:%M:%S'),level,current_stage,message),file=log_path,append=TRUE);emit('log',level=tolower(level),stage=current_stage,message=message)}
set_stage<-function(stage,label,progress,detail=NULL){current_stage<<-stage;write_log('INFO',paste0('Tahap: ',label));emit('progress',stage=stage,label=label,progress=as.numeric(progress),detail=detail)}
stop_run<-function(...)stop(paste0(...),call.=FALSE)
safe_write_sf<-function(x,path)suppressWarnings(st_write(x,path,delete_layer=TRUE,quiet=TRUE))
manifest_file<-function(folder)file.path(folder,'period_manifest.json')
read_manifest<-function(folder){f<-manifest_file(folder);if(!file.exists(f))stop_run('period_manifest.json tidak ditemukan: ',folder);jsonlite::fromJSON(f,simplifyVector=TRUE)}
resolve_file<-function(folder,rel){if(is.null(rel)||!length(rel)||is.na(rel[1])||!nzchar(rel[1]))return('');file.path(folder,rel[1])}
safe_spread<-function(v){v<-v[is.finite(v)];if(length(v)<2L)return(NA_real_);max(v)-min(v)}
safe_neg<-function(v){v<-v[is.finite(v)];if(!length(v))return(0L);sum(v<0)}
upper_fence<-function(x){x<-x[is.finite(x)];if(length(x)<4L)return(Inf);as.numeric(quantile(x,.75,names=FALSE))+1.5*IQR(x)}
make_report<-function(summary,preview,path){esc<-function(x){x<-as.character(x);x<-gsub('&','&amp;',x,fixed=TRUE);x<-gsub('<','&lt;',x,fixed=TRUE);x<-gsub('>','&gt;',x,fixed=TRUE);x};scalar<-vapply(summary,function(x)length(x)==1L&&!is.list(x),logical(1));rows<-paste0('<tr><th>',esc(names(summary)[scalar]),'</th><td>',esc(vapply(summary[scalar],function(x)ifelse(is.null(x)||is.na(x),'',as.character(x)),character(1))),'</td></tr>',collapse='');ph<-'';if(nrow(preview)){hr<-paste0('<th>',esc(names(preview)),'</th>',collapse='');bd<-apply(preview,1,function(r)paste0('<tr>',paste0('<td>',esc(r),'</td>',collapse=''),'</tr>'));ph<-paste0('<h2>Preview decision</h2><table><tr>',hr,'</tr>',paste(bd,collapse=''),'</table>')};writeLines(paste0('<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Segoe UI;background:#0b0f11;color:#e7edee;padding:28px}h1,h2{color:#e3a73f}table{border-collapse:collapse;width:100%}th,td{border:1px solid #263135;padding:7px;text-align:left}th{color:#e3a73f;background:#171f22}</style></head><body><h1>SawitHeight R — Compare 2 Periods</h1><p>Operational output: RECHECK / NO_RECHECK. Detailed status retained for audit.</p><table>',rows,'</table>',ph,'</body></html>'),path,useBytes=TRUE)}

validate_config<-function(deep=FALSE){
  set_stage('validation','Validasi dua period package',3)
  a<-as.character(inputs$prev_package%||%''); b<-as.character(inputs$curr_package%||%'')
  if(!dir.exists(a))stop_run('Folder package PREV tidak ditemukan.'); if(!dir.exists(b))stop_run('Folder package CURR tidak ditemukan.')
  if(normalizePath(a,winslash='/',mustWork=FALSE)==normalizePath(b,winslash='/',mustWork=FALSE))stop_run('Package PREV dan CURR tidak boleh sama.')
  ma<-read_manifest(a); mb<-read_manifest(b)
  if(is.null(ma$package_type)||is.null(mb$package_type)||ma$package_type!='SAWITHEIGHT_PERIOD'||mb$package_type!='SAWITHEIGHT_PERIOD')stop_run('Folder bukan period package SawitHeight yang valid.')
  if(toupper(ma$period_code)==toupper(mb$period_code))stop_run('Kode periode PREV dan CURR sama.')
  prev_metrics<-resolve_file(a,ma$files$metrics_csv); prev_shp<-resolve_file(a,ma$files$metrics_shp)
  curr_metrics<-resolve_file(b,mb$files$metrics_csv); curr_shp<-resolve_file(b,mb$files$metrics_shp)
  if(!file.exists(prev_metrics)||!file.exists(prev_shp))stop_run('Metrics CSV/SHP package PREV tidak lengkap.')
  if(!file.exists(curr_metrics)||!file.exists(curr_shp))stop_run('Metrics CSV/SHP package CURR tidak lengkap.')
  bp<-as_num(ma$methodology$buffer_radius_m); bc<-as_num(mb$methodology$buffer_radius_m); vhp<-as_num(ma$methodology$min_veg_h_m); vhc<-as_num(mb$methodology$min_veg_h_m)
  if(!isTRUE(all.equal(bp,bc,tolerance=1e-9)))stop_run('Buffer radius period package berbeda. Proses ulang dengan parameter konsisten.')
  if(!isTRUE(all.equal(vhp,vhc,tolerance=1e-9)))stop_run('MIN_VEG_H period package berbeda. Proses ulang dengan parameter konsisten.')
  if(deep)emit('validation-result',status='success',message=paste('Package',ma$period_code,'dan',mb$period_code,'valid untuk comparison.'))
  invisible(TRUE)
}

run_pipeline<-function(){
  validate_config(FALSE);prev_dir<-normalizePath(inputs$prev_package,winslash='/',mustWork=TRUE);curr_dir<-normalizePath(inputs$curr_package,winslash='/',mustWork=TRUE);mp<-read_manifest(prev_dir);mc<-read_manifest(curr_dir);PREV<-toupper(mp$period_code);CURR<-toupper(mc$period_code)
  set_stage('load','Load period packages',8);write_log('INFO',paste('PREV package:',prev_dir));write_log('INFO',paste('CURR package:',curr_dir));write_log('INFO',paste('Compare:',PREV,'→',CURR))
  prev_csv<-resolve_file(prev_dir,mp$files$metrics_csv);curr_csv<-resolve_file(curr_dir,mc$files$metrics_csv);prev_shp<-resolve_file(prev_dir,mp$files$metrics_shp);curr_shp<-resolve_file(curr_dir,mc$files$metrics_shp)
  a<-read.csv(prev_csv,stringsAsFactors=FALSE,check.names=FALSE);b<-read.csv(curr_csv,stringsAsFactors=FALSE,check.names=FALSE);if(!('tree_id'%in%names(a))||!('tree_id'%in%names(b)))stop_run('tree_id tidak tersedia pada metrics.');if(anyDuplicated(a$tree_id)||anyDuplicated(b$tree_id))stop_run('tree_id pada metrics tidak unik.')
  write_log('INFO',paste('TREE_ID PREV:',nrow(a),'| CURR:',nrow(b)))
  set_stage('join','Join TREE_ID & delta multi-metrik',20);ra<-c('n_all','n_veg','veg_ratio','p95','p99','top10','top20','top30','data_ok','canopy_support','peer_group');for(nm in ra){if(!(nm%in%names(a)))a[[nm]]<-NA;if(!(nm%in%names(b)))b[[nm]]<-NA};names(a)[names(a)%in%ra]<-paste0(names(a)[names(a)%in%ra],'_prev');names(b)[names(b)%in%ra]<-paste0(names(b)[names(b)%in%ra],'_curr');pair<-full_join(a,b,by='tree_id')
  pair<-pair%>%mutate(d_p95=p95_curr-p95_prev,d_p99=p99_curr-p99_prev,d_t10=top10_curr-top10_prev,d_t20=top20_curr-top20_prev,d_t30=top30_curr-top30_prev)
  pair$metric_spread<-apply(pair[,c('d_p95','d_t10','d_t20','d_t30')],1,safe_spread);pair$n_negative<-apply(pair[,c('d_p95','d_t10','d_t20','d_t30')],1,safe_neg);spread_cut<-upper_fence(pair$metric_spread);pair$metric_disagree<-is.finite(pair$metric_spread)&pair$metric_spread>spread_cut
  set_stage('uncertainty','Technical uncertainty proxy',38);sigma_prev<-as_num(mp$terrain_qc$nmad_m);sigma_curr<-as_num(mc$terrain_qc$nmad_m);T_TERRAIN<-if(is.finite(sigma_prev)&&is.finite(sigma_curr))sqrt(sigma_prev^2+sigma_curr^2)else NA_real_;T_METRIC<-if(any(is.finite(pair$metric_spread)))as.numeric(quantile(pair$metric_spread,.95,na.rm=TRUE,names=FALSE))else NA_real_;tt<-c(T_TERRAIN,T_METRIC);tt<-tt[is.finite(tt)];T_TECH<-if(length(tt))max(tt)else NA_real_;write_log('INFO',paste('T_TERRAIN =',ifelse(is.finite(T_TERRAIN),round(T_TERRAIN,4),'NA'),'m'));write_log('INFO',paste('T_METRIC =',ifelse(is.finite(T_METRIC),round(T_METRIC,4),'NA'),'m'));write_log('INFO',paste('T_TECH =',ifelse(is.finite(T_TECH),round(T_TECH,4),'NA'),'m'))
  set_stage('peer','Peer-based lower residual limits',55);peer_prev<-if('peer_group_prev'%in%names(pair))pair$peer_group_prev else rep(NA_character_,nrow(pair));use_peer<-sum(!is.na(peer_prev)&nzchar(peer_prev))>=4L;if(use_peer){pair$peer<-as.character(peer_prev);peer_source<-as.character(mp$peer_field%||%'peer_group')}else{vh<-pair$p95_prev[is.finite(pair$p95_prev)];if(length(vh)>=4L){q<-quantile(vh,probs=c(.25,.5,.75),na.rm=TRUE,names=FALSE);br<-unique(c(-Inf,q,Inf));if(length(br)>=3L&&all(is.finite(br[is.finite(br)]))){pair$peer<-as.character(cut(pair$p95_prev,breaks=br,include.lowest=TRUE,labels=FALSE))}else pair$peer<-'1'}else pair$peer<-'1';peer_source<-'P95_PREV_QUARTILE'};write_log('INFO',paste('Peer source:',peer_source))
  eligible<-pair$canopy_support_prev%in%TRUE & pair$canopy_support_curr%in%TRUE & !pair$metric_disagree & is.finite(pair$d_p95);pls<-list();for(g in unique(pair$peer)){x<-pair$d_p95[eligible&pair$peer==g];x<-x[is.finite(x)];if(!length(x))next;q1<-as.numeric(quantile(x,.25,names=FALSE));q3<-as.numeric(quantile(x,.75,names=FALSE));iq<-IQR(x);lp<-if(length(x)>=4L&&is.finite(iq))q1-1.5*iq else NA_real_;lr<-if(is.finite(lp)&&is.finite(T_TECH))min(lp,-T_TECH)else NA_real_;pls[[length(pls)+1L]]<-data.frame(peer=as.character(g),q1=q1,q3=q3,iqr=iq,lower_peer=lp,n_peer=length(x),lower_residual=lr)};peer_limits<-if(length(pls))bind_rows(pls)else data.frame(peer=character(),q1=numeric(),q3=numeric(),iqr=numeric(),lower_peer=numeric(),n_peer=integer(),lower_residual=numeric());pair<-left_join(pair,peer_limits,by='peer');peer_csv<-file.path(qc_dir,paste0('peer_limits_',PREV,'_',CURR,'.csv'));write.csv(peer_limits,peer_csv,row.names=FALSE)
  set_stage('decision','Decision logic → RECHECK / NO_RECHECK',72);status<-rep('REVIEW',nrow(pair));cond<-!(pair$data_ok_curr%in%TRUE);status[cond]<-'TECH_DATA_GAP_CURRENT';cond<-status=='REVIEW'&!(pair$data_ok_prev%in%TRUE);status[cond]<-'TECH_DATA_GAP_PREVIOUS';cond<-status=='REVIEW'&pair$canopy_support_prev%in%TRUE&!(pair$canopy_support_curr%in%TRUE)&pair$data_ok_curr%in%TRUE;status[cond]<-'CANOPY_LOSS_OR_RECONSTRUCTION';cond<-status=='REVIEW'&!(pair$canopy_support_prev%in%TRUE)&!(pair$canopy_support_curr%in%TRUE)&pair$data_ok_prev%in%TRUE&pair$data_ok_curr%in%TRUE;status[cond]<-'NO_CANOPY_SUPPORT_BOTH';cond<-status=='REVIEW'&pair$metric_disagree%in%TRUE;status[cond]<-'TECH_METRIC_DISAGREEMENT';cond<-status=='REVIEW'&pair$canopy_support_prev%in%TRUE&pair$canopy_support_curr%in%TRUE&is.finite(pair$lower_residual)&is.finite(pair$d_p95)&pair$d_p95<pair$lower_residual&pair$n_negative>=3L;status[cond]<-'NEGATIVE_HEIGHT_OUTLIER';cond<-status=='REVIEW'&pair$canopy_support_prev%in%TRUE&pair$canopy_support_curr%in%TRUE&is.finite(T_TECH)&is.finite(pair$d_p95)&abs(pair$d_p95)<=T_TECH;status[cond]<-'STABLE_NO_DETECTABLE_CHANGE';cond<-status=='REVIEW'&pair$canopy_support_curr%in%TRUE;status[cond]<-'PRESENT_NO_HARD_RESIDUAL';if(!is.finite(T_TECH)){cond<-status%in%c('STABLE_NO_DETECTABLE_CHANGE','PRESENT_NO_HARD_RESIDUAL');status[cond]<-'TECH_UNCERTAINTY_UNAVAILABLE'};pair$status_detail<-status;pair$recommendation<-ifelse(status%in%c('STABLE_NO_DETECTABLE_CHANGE','PRESENT_NO_HARD_RESIDUAL'),'NO_RECHECK','RECHECK');pair$residual_flag<-pair$recommendation=='RECHECK';write_log('INFO',paste('RECHECK:',sum(pair$residual_flag),'| NO_RECHECK:',sum(!pair$residual_flag)));sc<-sort(table(pair$status_detail),decreasing=TRUE);write_log('INFO',paste('Detail:',paste(names(sc),as.integer(sc),sep='=',collapse=' | ')))
  set_stage('geometry','Build monitoring & recheck geometry',84);sf_prev<-st_read(prev_shp,quiet=TRUE)%>%select(tree_id);sf_curr<-st_read(curr_shp,quiet=TRUE)%>%select(tree_id);if(!identical(st_crs(sf_prev)$wkt,st_crs(sf_curr)$wkt))stop_run('CRS metrics SHP PREV dan CURR berbeda.');base_geom<-sf_curr;miss<-setdiff(sf_prev$tree_id,sf_curr$tree_id);if(length(miss))base_geom<-rbind(base_geom,sf_prev[sf_prev$tree_id%in%miss,,drop=FALSE]);attr<-pair%>%transmute(tree_id=tree_id,p95_prev=p95_prev,p95_curr=p95_curr,d_p95=d_p95,d_p99=d_p99,d_t10=d_t10,d_t20=d_t20,d_t30=d_t30,sprd=metric_spread,nneg=n_negative,can_p=canopy_support_prev,can_c=canopy_support_curr,ttech=T_TECH,status=status_detail,rekom=recommendation,res_flag=residual_flag);pair_sf<-left_join(base_geom,attr,by='tree_id');monitor_shp<-file.path(shp_dir,paste0('monitoring_',PREV,'_',CURR,'.shp'));safe_write_sf(pair_sf,monitor_shp)
  recheck_point<-pair_sf[pair_sf$rekom=='RECHECK',,drop=FALSE];recheck_point_path<-'';recheck_buffer_path<-'';recheck_zone_path<-'';zone_csv<-'';zone_count<-0L;if(nrow(recheck_point)>0L){recheck_point_path<-file.path(shp_dir,paste0('recheck_point_',PREV,'_',CURR,'.shp'));safe_write_sf(recheck_point,recheck_point_path);buffer_m<-as_num(mc$methodology$buffer_radius_m,2);rb<-st_buffer(recheck_point,dist=buffer_m);recheck_buffer_path<-file.path(shp_dir,paste0('recheck_buffer_',PREV,'_',CURR,'.shp'));safe_write_sf(rb,recheck_buffer_path);zg<-st_union(rb);zg<-suppressWarnings(st_cast(zg,'POLYGON'));rz<-st_sf(ZONE_ID=seq_along(zg),geometry=zg);hit<-st_intersects(rz,recheck_point);rz$N_TREE<-lengths(hit);rz$REKOM<-'RECHECK';rz$REASON<-vapply(hit,function(ix){if(!length(ix))return('');paste(sort(unique(recheck_point$status[ix])),collapse='|')},character(1));rz$AREA_M2<-as.numeric(st_area(rz));recheck_zone_path<-file.path(shp_dir,paste0('recheck_zone_',PREV,'_',CURR,'.shp'));safe_write_sf(rz,recheck_zone_path);zone_csv<-file.path(run_dir,paste0('recheck_zone_',PREV,'_',CURR,'.csv'));write.csv(st_drop_geometry(rz),zone_csv,row.names=FALSE);zone_count<-nrow(rz)}
  qc_plot_files<-character(0)
  try({
    x<-pair$d_p95[is.finite(pair$d_p95)]
    if(length(x)>1L){f<-file.path(qc_dir,paste0('hist_delta_p95_',PREV,'_',CURR,'.png'));png(f,1600,1000,res=150);hist(x,breaks='FD',main=paste('Delta P95',PREV,'to',CURR),xlab='Delta P95 (m)');abline(v=0,lty=2);if(is.finite(T_TECH))abline(v=c(-T_TECH,T_TECH),lty=3);dev.off();qc_plot_files<-c(qc_plot_files,f)}
  },silent=TRUE)
  set_stage('export','Export comparison package',94);pair_csv<-file.path(run_dir,paste0('comparison_',PREV,'_',CURR,'.csv'));write.csv(pair,pair_csv,row.names=FALSE);detail_counts<-as.list(as.integer(sc));names(detail_counts)<-names(sc);preview<-head(pair[,c('tree_id','p95_prev','p95_curr','d_p95','status_detail','recommendation'),drop=FALSE],25);summary<-list(task='compare',app_version=as.character(cfg$app$version%||%'0.8.0'),run_dir=run_dir,prev_period_code=PREV,curr_period_code=CURR,tree_count=nrow(pair),t_terrain_m=T_TERRAIN,t_metric_m=T_METRIC,t_tech_m=T_TECH,metric_spread_cut_m=spread_cut,peer_source=peer_source,delta_p95_median=if(any(is.finite(pair$d_p95)))median(pair$d_p95,na.rm=TRUE)else NA_real_,recheck_count=sum(pair$recommendation=='RECHECK'),no_recheck_count=sum(pair$recommendation=='NO_RECHECK'),recheck_pct=round(mean(pair$recommendation=='RECHECK')*100,2),zone_count=zone_count,status_detail_counts=detail_counts,preview=preview)
  summary_path<-file.path(run_dir,'comparison_summary.json');jsonlite::write_json(summary,summary_path,pretty=TRUE,auto_unbox=TRUE,na='null');report_path<-file.path(run_dir,paste0('report_compare_',PREV,'_',CURR,'.html'));make_report(summary,preview,report_path);outputs<-c(pair_csv,monitor_shp,peer_csv,recheck_point_path,recheck_buffer_path,recheck_zone_path,zone_csv,qc_plot_files,summary_path,report_path,log_path);outputs<-unique(outputs[nzchar(outputs)&file.exists(outputs)]);manifest<-file.path(run_dir,'output_manifest.csv');write.csv(data.frame(file=basename(outputs),path=outputs),manifest,row.names=FALSE);summary$output_files<-unique(c(outputs,manifest));jsonlite::write_json(summary,summary_path,pretty=TRUE,auto_unbox=TRUE,na='null');set_stage('complete',paste('Comparison',PREV,'→',CURR,'selesai'),100);emit('result',task='compare',status='success',runDir=run_dir,summaryPath=summary_path,reportPath=report_path,summary=summary);write_log('INFO','Comparison selesai.')
}
status_code<-0L
withCallingHandlers(tryCatch({if(mode=='validate'){validate_config(TRUE);set_stage('complete','Validasi comparison berhasil',100);emit('validation-result',status='success',message='Dua period package valid untuk dibandingkan.')}else run_pipeline()},error=function(e){status_code<<-10L;msg<-conditionMessage(e);try(cat(sprintf('[%s] [FATAL] [%s] %s\n',format(Sys.time(),'%Y-%m-%d %H:%M:%S'),current_stage,msg),file=log_path,append=TRUE),silent=TRUE);emit('fatal',stage=current_stage,message=msg,runDir=run_dir,logPath=log_path)}),warning=function(w){try(write_log('WARNING',conditionMessage(w)),silent=TRUE);invokeRestart('muffleWarning')})
quit(status=status_code)
